public static class FixArrivalProxy19 {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit only");const string A="Assets/ShooterSurvival/Models/Chapters/Chapters45/Ch5Toon20261004";string rec="outputs/ch5-toon-2026-10-04/recovery-before-arrival-proxy.unity";if(File.Exists(rec))throw new Exception("Already applied");var root=GameObject.Find("Chapter45_World/DetailedMall_20261003").transform;var metal=AssetDatabase.LoadAssetAtPath<Material>(A+"/Escalator brushed graphite.mat");var treads=root.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name=="Arrival continuity / Metal escalator tread").ToArray();if(metal==null||treads.Length!=96||treads.GroupBy(r=>r.transform.parent).Count()!=3)throw new Exception("Unexpected arrival proxy inventory");File.Copy(SceneManager.GetActiveScene().path,rec,false);int n=0;foreach(var group in treads.GroupBy(r=>r.transform.parent)){var created=new List<GameObject>();var owner=new GameObject("Toon arrival proxy metal risers").transform;owner.SetParent(group.Key,false);foreach(var r in group){r.sharedMaterial=metal;var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="Arrival closed metal riser";g.transform.SetParent(owner,false);g.transform.SetPositionAndRotation(r.transform.position-r.transform.forward*.245f-Vector3.up*.14f,r.transform.rotation);g.transform.localScale=new Vector3(5,.29f,.06f);Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=metal;created.Add(g);}var mesh=new Mesh();mesh.CombineMeshes(created.Select(g=>new CombineInstance{mesh=g.GetComponent<MeshFilter>().sharedMesh,transform=owner.worldToLocalMatrix*g.transform.localToWorldMatrix}).ToArray());AssetDatabase.CreateAsset(mesh,A+"/Arrival-closed-risers-"+(n++)+".asset");owner.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;var rr=owner.gameObject.AddComponent<MeshRenderer>();rr.sharedMaterial=metal;rr.shadowCastingMode=ShadowCastingMode.Off;foreach(var g in created)Object.DestroyImmediate(g);}
EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());var result=new{arrivalProxyTreads=treads.Length,riserBatches=n,newColliders=0,originalTransformsAndLiftCodeUntouched=true};var jt=AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert");File.WriteAllText("outputs/ch5-toon-2026-10-04/arrival-proxy-correction.json",(string)jt.GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{(object)result}));return result;}}
